/**************************************************************************/
/**************************************************************************/
/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   Module execution harness: protected module lifecycle                */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* A user-mode, memory-protected module is loaded, granted the shared area,
   started, left to exercise the kernel through its dispatcher, stopped and
   unloaded -- twice, so that the second cycle shows the first gave back what
   it took.  The module must run unprivileged and must not fault.  */

#include "harness_checks.h"

#define LIFECYCLE_CYCLES        ((ULONG) 2UL)
#define MODULE_WAIT_TICKS       ((ULONG) 500UL)
#define PROTECTED_PROPERTIES    ((ULONG) 0x02000007UL)  /* GNU; user mode, memory protection, shared memory */

extern UCHAR                    module_services_protected[];

static TXM_MODULE_INSTANCE      test_module;

#ifdef MODULE_QEMU_CORTEX_M55
/* Check MPU limit attributes and the number of grants a loaded module can hold.  */
static VOID  m55_check_loaded_grants(VOID)
{

ULONG   slot;
ULONG   address;
ULONG   limit;


    harness_expect("unaligned shared address",
                   (ULONG) txm_module_manager_external_memory_enable(&test_module, (VOID *) (MODULE_SHARED_BASE + 1UL),
                       MODULE_SHARED_SIZE, TXM_MODULE_ATTRIBUTE_READ_WRITE), (ULONG) TXM_MODULE_ALIGNMENT_ERROR);
    limit = test_module.txm_module_instance_mpu_registers[TXM_MODULE_MPU_SHARED_INDEX].txm_module_mpu_region_limit_address;
    harness_expect("shared region limit attributes", limit & (TXM_MODULE_MPU_ALIGNMENT - 1UL),
                   TXM_MODULE_ATTRIBUTE_INDEX | TXM_MODULE_ATTRIBUTE_REGION_ENABLE);

    for (slot = 1UL; slot < TXM_MODULE_MPU_SHARED_ENTRIES; slot++)
    {
        address = MODULE_SHARED_BASE + (slot * MODULE_SHARED_SIZE);
        harness_expect("additional shared region",
                       (ULONG) txm_module_manager_external_memory_enable(&test_module, (VOID *) address,
                           MODULE_SHARED_SIZE, TXM_MODULE_ATTRIBUTE_READ_WRITE), (ULONG) TX_SUCCESS);
    }
    address = MODULE_SHARED_BASE + (slot * MODULE_SHARED_SIZE);
    harness_expect("no shared regions left",
                   (ULONG) txm_module_manager_external_memory_enable(&test_module, (VOID *) address,
                       MODULE_SHARED_SIZE, TXM_MODULE_ATTRIBUTE_READ_WRITE), (ULONG) TX_NO_MEMORY);
}
#endif


VOID  harness_test(VOID)
{
ULONG   cycle;
ULONG   available_before;

    harness_print("Module lifecycle: protected module, load/start/stop/unload twice\n");

#ifdef MODULE_QEMU_CORTEX_M55
    harness_expect("grant without a module", (ULONG) harness_shared_grant(TX_NULL), (ULONG) TX_PTR_ERROR);
    harness_expect("grant to unloaded module", (ULONG) harness_shared_grant(&test_module), (ULONG) TX_PTR_ERROR);
#endif

    available_before = harness_module_pool_available();

    for (cycle = 1UL; cycle <= LIFECYCLE_CYCLES; cycle++)
    {
        harness_value("cycle", cycle);

        harness_shared_clear();
        MODULE_SHARED[MODULE_IN_CYCLE] = cycle;

        harness_expect("memory load", (ULONG) txm_module_manager_memory_load(&test_module, "services protected",
                                                                             (VOID *) module_services_protected),
                       (ULONG) TX_SUCCESS);
        harness_expect("module properties", test_module.txm_module_instance_property_flags, PROTECTED_PROPERTIES);
        harness_expect("shared area grant", (ULONG) harness_shared_grant(&test_module), (ULONG) TX_SUCCESS);
#ifdef MODULE_QEMU_CORTEX_M55
        m55_check_loaded_grants();
#endif
        harness_expect("module start", (ULONG) txm_module_manager_start(&test_module), (ULONG) TX_SUCCESS);
#ifdef MODULE_QEMU_CORTEX_M55
        harness_expect("grant after module start", (ULONG) harness_shared_grant(&test_module), (ULONG) TX_START_ERROR);
#endif
        harness_expect("module finished", (ULONG) harness_wait_for_module(MODULE_WAIT_TICKS), (ULONG) TX_TRUE);

        harness_check_services(cycle);
        harness_expect("module ran unprivileged",
                       MODULE_SHARED[MODULE_OUT_CONTROL] & CONTROL_NPRIV, CONTROL_NPRIV);
        harness_expect("no memory fault", harness_fault_count, 0UL);

        harness_expect("module stop", (ULONG) txm_module_manager_stop(&test_module), (ULONG) TX_SUCCESS);
        harness_expect("module unload", (ULONG) txm_module_manager_unload(&test_module), (ULONG) TX_SUCCESS);
        harness_expect("module memory returned", harness_module_pool_available(), available_before);
    }
}
